    "theme": "Le plus beau des récits : l'histoire complète de Joseph — le songe, le puits, la tentation, la prison, l'interprétation des rêves, l'élévation en Égypte et le pardon aux frères — une seule narration continue sur la fidélité de Dieu envers les patients",
    "note_pedagogique": "Unique dans le Coran : une seule histoire déroulée d'un bout à l'autre de la sourate, qualifiée d'aḥsan al-qaṣaṣ, « le plus beau des récits ». Révélée pendant « l'année de la tristesse » du Prophète, elle enseigne que la trahison des proches, l'injustice et la prison peuvent être les marches d'une élévation voulue par Dieu. Elle culmine sur le pardon de Joseph : « Nul reproche contre vous aujourd'hui. »",
